async function termDefaultClockModel(){const m=await clockModel(),snapshot=m.journal.directCreates[0].captured.find(r=>r.table==='contract_term_snapshot');snapshot.row.effective_at=snapshot.row.created_at;const metadata=JSON.parse(fs.readFileSync('tmp/rust-r2m-continuation01/m4-term-default-birth-source-metadata01.json')),originalLedgerRef={file:'/controlled-original-ledger.json',bytes:1,rawBytesSha256:'a'.repeat(64)},report=metadata.births.find(r=>r.backend===m.journal.backend);report.originalLedger=structuredClone(originalLedgerRef);report.originalDirectTransaction='200';report.originalExpectedXmin='200';report.capturedRowKeys=Object.keys(snapshot.row);return{...m,termDefaultMetadata:metadata,originalLedgerRef,snapshot:snapshot.row}}
test('only original K omitted snapshot effective_at couples to its exact same direct-birth created_at with honest current-catalogue scope',async()=>{const m=await termDefaultClockModel(),domain=await createAttachmentDomainProjection(m),row=domain.row('contract_term_snapshot',m.snapshot);assert(row.effective_at.$sourceClock);assert.equal(row.effective_at.coupledToSourceSlot,row.created_at.$sourceClock);assert.equal(row.effective_at.catalogueTiming,'current-not-original-run');assert.equal(domain.receipt().KTermDefaultCoupling.sites,1);assert.equal(m.snapshot.effective_at,m.snapshot.created_at);assert.equal(domain.receipt().KTermDefaultCoupling.currentCatalogueNotHistoricalReceipt,true)});
