test('Native-only R4 detail root generatedAt is original source/window bound; other endpoint/nesting/precision remains strict',async()=>{const m=await nativeDetailClockModel(),domain=await createAttachmentDomainProjection(m),body={handoverId:m.handover.id,generatedAt:'2026-10-31T00:00:00.480Z',nested:{generatedAt:'literal'},keep:'all-fields'};const actual=domain.body(body,m.step,m.route);assert.equal(actual.generatedAt.$sourceClock,'ProjectHandoverQueryService.buildProjectHandoverDetail.generatedAt');assert.deepEqual(actual.nested,body.nested);assert.equal(actual.keep,body.keep);assert.equal(domain.body(body,{...m.step,id:'M4.2.unlisted'},m.route).generatedAt,body.generatedAt);assert.throws(()=>domain.body({...body,generatedAt:'2026-10-31T00:00:00.491Z'},m.step,m.route));assert.throws(()=>domain.body({...body,generatedAt:'2026-10-31T00:00:00.480001Z'},m.step,m.route));assert.throws(()=>domain.body(body,m.step,{...m.route,context:{...m.route.context,index:99}}));assert.throws(()=>domain.body({...body,handoverId:id(999)},m.step,m.route));assert.equal(m.sourceEngine.nativeHandoverClockSource().sourcePins.length,2)});
async function checklistDtoModel(selected){const m=await refreshClockModel();Object.assign(m.attachment,{display_name:'controlled-original-name.txt',category:'demand',security_level:'normal'});for(const record of m.records.filter(r=>r.data.kind==='complete-full107-private-facts'))for(const row of record.data.record.tables.find(t=>t.table==='attachment')?.rows??[])if(row.id===m.attachment.id)Object.assign(row,{display_name:m.attachment.display_name,category:m.attachment.category,security_level:m.attachment.security_level});Object.assign(m.selection,{display_name:'controlled-original-name.txt',category:'demand',security_level:'normal',row_version:1});const original=m.steps[0],rows=selected?original.after.rows:original.before.rows,step=selected?original:{...original,id:'M4.2.checklist',before:{rows},after:{rows}},route=selected?m.refreshRequest:{...m.refreshRequest,method:'GET',path:'/api/project-handovers/'+m.handover.id+'/attachment-checklist'};m.dtoSites=[{logicalCase:'M4.2',stepId:selected?'refresh':'checklist',path:'response.items[0]',idField:'handoverId',table:'project_handover'}];const node=m.sourceEngine.replayChecklistItem(selected?'selection':'candidate',selected?{selection:m.selection}:{handover:m.handover,attachment:m.attachment,candidate:{status:'included',selectionReason:null,exclusionReason:null,sourceRefs:m.selection.source_refs}});return{...m,step,route,node}}
