test('actual Reader domain call forwards both pinned default metadata and original ledger reference to real coupling implementation',async()=>{const m=await termDefaultClockModel(),source=fs.readFileSync('tools/rust-r2m/compare-api-attachments-reader.mjs','utf8'),ast=ts.createSourceFile('reader.mjs',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS),calls=[];function find(n){if(ts.isCallExpression(n)&&n.expression.getText(ast)==='createAttachmentDomainProjection')calls.push(n);ts.forEachChild(n,find)}find(ast);assert.equal(calls.length,1);const actual=new Function('createAttachmentDomainProjection','j','cap','authority','types','records','steps','owner','sourceEngine','defaultCatalog','dtoSites','payloads','termDefault','journalRef','return '+calls[0].getText(ast)),args=[createAttachmentDomainProjection,m.journal,m.sourceCap,m.authority,m.types,m.records,m.steps,{startedAt:m.window.startedAt,finishedAt:m.window.finishedAt},m.sourceEngine,m.defaultCatalog,m.dtoSites,m.payloads,{data:m.termDefaultMetadata},m.originalLedgerRef],domain=await actual(...args);assert(domain.row('contract_term_snapshot',m.snapshot).effective_at.$sourceClock);const bad=[...args];bad[13]=undefined;await assert.rejects(()=>actual(...bad));});
